mapper.select:
SELECT n.notif_id, n.user_id, n.sender_id, n.notif_type, n.target_id, n.target_type, n.story_id, n.is_read, n.create_time, n.content, su.nick_name AS sender_nick_name, su.avatar AS sender_avatar, s.title AS story_title, /* 目标内容摘要：根据目标类型取对应表的内容 */ CASE n.target_type WHEN 0 THEN LEFT(st.setting_content, 50) WHEN 1 THEN LEFT(b.content, 50) WHEN 2 THEN LEFT(c.content, 50) END AS target_content_preview FROM zhw_notification n LEFT JOIN zhw_user su ON su.user_id = n.sender_id LEFT JOIN zhw_story st ON st.story_id = n.story_id LEFT JOIN zhw_story s ON s.story_id = n.story_id LEFT JOIN zhw_branch b ON b.branch_id = n.target_id AND n.target_type = 1 LEFT JOIN zhw_comment c ON c.comment_id = n.target_id AND n.target_type = 2 WHERE n.user_id = #{userId}
AND n.notif_type = #{notifType}
ORDER BY n.create_time DESC

